UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Virgül varlığı tek başına bir cümleciğin [[q]]defining[[/q]] mi [[q]]non-defining[[/q]] mi olduğunu belirler:", "items": [{"heading": "Virgül Var mı, Yok mu?", "badge": "Defining / Non-defining", "sub_rules": [{"condition": "Boşluktan hemen [[amber]]ÖNCE virgül VARSA[[/amber]] cümlecik non-defining'dir (ek bilgi verir, çıkarılsa temel anlam bozulmaz):", "from": "virgüllü (non-defining)", "to": "\"that\" KULLANILAMAZ, zamir atılamaz"}, {"condition": "Boşluktan önce [[amber]]virgül YOKSA[[/amber]] cümlecik defining'dir (ismi tanımlar, çıkarılırsa anlam eksik kalır):", "from": "virgülsüz (defining)", "to": "\"that\" kullanılabilir"}]}, {"heading": "Bütün Cümleyi Niteleyen \"which\"", "badge": "Özel Kullanım", "body": [{"type": "text", "text": "[[q]]\"which\"[[/q]], virgülden sonra gelip kendisinden önceki İSMİ değil, [[dark]]ÖNCEKİ CÜMLENİN TAMAMINI[[/dark]] nitelediği özel bir kullanıma da sahiptir."}, {"type": "text", "text": "Bu kullanımda [[amber]]who/that/where[[/amber]] asla [[b]]\"which\"[[/b]]'in yerini alamaz."}, {"type": "example_check", "correct": "He passed the exam, which surprised everyone", "wrong_note": "\"that\" burada \"which\" yerine kullanılamaz çünkü virgülden sonra gelmiştir ve bir ismi değil tüm cümleyi nitelemektedir"}]}], "examples": [{"sentence": "My brother, who lives in Izmir, is visiting us next week.", "answer_word": "who", "reasoning": "Virgülle ayrılmış (non-defining) olduğu için [[bad]]\"that\"[[/bad]] kullanılamaz; doğru cevap [[right]]\"who\"[[/right]]dur. [[wrong]]\"My brother that lives in Izmir...\"[[/wrong]] yanlıştır çünkü non-defining clause'da \"that\" yasaktır."}, {"sentence": "He failed the exam, which disappointed his parents greatly.", "answer_word": "which", "reasoning": "Virgülden sonra gelen bu zamir önceki isimlerden birini değil, sınavı geçememe olayının [[dark]]TAMAMINI[[/dark]] nitelediği için doğru cevap [[right]]\"which\"[[/right]]tir; [[wrong]]\"that\"[[/wrong]] burada hem virgülden sonra geldiği hem de bir ismi değil tüm cümleyi nitelediği için kesinlikle yanlıştır."}, {"sentence": "The book that won last year's literary prize has just been translated into fifteen languages.", "answer_word": "that", "reasoning": "Boşluktan önce virgül YOK, bu cümlecik hangi kitaptan bahsedildiğini tanımladığı için defining'dir → doğru cevap [[right]]\"that\"[[/right]] (ya da \"which\") olup burada \"that\" serbestçe kullanılabilir; cümlede virgül olsaydı [[wrong]]\"that\"[[/wrong]] kesinlikle yanlış olurdu."}, {"sentence": "Professor Aydın, whose research on climate change has been cited worldwide, will give the keynote speech.", "answer_word": "whose", "reasoning": "Virgülle ayrılmış bir non-defining cümlecik ve iyelik anlamı (onun araştırması) taşıdığı için doğru cevap [[right]]\"whose\"[[/right]]tur; bu yapıda da [[bad]]\"that\"[[/bad]] kullanılamaz çünkü virgülden hemen sonra gelmiştir."}]}$tagbd$::jsonb WHERE id = '018a0797-2f2c-4927-9b3a-65aec2dda2de';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]whose[[/q]] / [[q]]where[[/q]] / [[q]]when[[/q]] ayrımını yaparken boşluktan ardından gelen yapıya bak:", "items": [{"heading": "Ardından Gelen Yapıya Göre Zamir", "badge": "whose / where / when", "sub_rules": [{"condition": "[[amber]]\"whose\"[[/amber]]'tan sonra MUTLAKA bir [[b]]İSİM[[/b]] gelir ve bu isim önceki isme [[dark]]AİTTİR[[/dark]]:", "from": "the scientist", "to": "whose research..."}, {"condition": "[[amber]]\"where\"[[/amber]] bir [[b]]YER[[/b]] isminden sonra gelir, ardından öznesi eksik olmayan TAM bir cümle gelir:", "from": "the school", "to": "where ... (tam cümle)"}, {"condition": "[[amber]]\"when\"[[/amber]] bir [[b]]ZAMAN[[/b]] isminden (the day, the year, the moment) sonra gelir:", "from": "the day", "to": "when ..."}]}, {"heading": "\"where\" Özne Göreviyle Kullanılamaz Tuzağı", "badge": "Sık Hata", "body": [{"type": "text", "text": "[[q]]\"where\"[[/q]] kendisi özne göreviyle kullanılamaz: [[bad]]\"the school where was built in 1990\"[[/bad]] gibi bir yapı [[dark]]YANLIŞTIR[[/dark]]."}, {"type": "example_check", "correct": "the school which/that was built in 1990", "wrong_note": "\"the school where was built in 1990\" yanlıştır"}]}, {"heading": "\"whose\" Sadece İnsanlar İçin mi?", "is_warning": true, "warning_label": "⚠️ Yanlış İnanış", "body": [{"type": "text", "text": "[[q]]\"whose\"[[/q]] sadece insanlar için değil, [[dark]]CANSIZ[[/dark]] varlıklar için de kullanılabilir (ör. \"the novel, whose ending...\")."}], "warning_text": "Bazı öğrenciler \"whose\"un sadece kişilerle kullanılabileceğini zannederek bu tür sorularda yanlış şıkka yönelir."}], "examples": [{"sentence": "The researcher whose findings challenged the earlier study works at MIT.", "answer_word": "whose", "reasoning": "Boşluktan sonra bir isim (\"findings\") var ve bu bulgular araştırmacıya [[dark]]AİT[[/dark]] → doğru cevap [[right]]\"whose\"[[/right]]tur. Benzer şekilde \"The city where I was born has changed a lot.\" cümlesinde \"city\" bir yer ismi ve ardından tam bir cümle (\"I was born\") geldiği için doğru cevap [[right]]\"where\"[[/right]]dir."}, {"sentence": "The company whose profits doubled last year plans to expand abroad.", "answer_word": "whose", "reasoning": "Boşluktan sonra bir isim (\"profits\") var ve bu kâr şirkete [[dark]]AİT[[/dark]] → doğru cevap [[right]]\"whose\"[[/right]]tur. \"The hotel where was fully booked offered us a room in a different branch.\" cümlesi ise yanlıştır çünkü [[wrong]]\"where\"[[/wrong]] özne göreviyle kullanılamaz; doğrusu \"The hotel which/that was fully booked...\" olmalıdır."}, {"sentence": "The novel, whose ending left many readers unsatisfied, became a surprise bestseller despite the criticism.", "answer_word": "whose", "reasoning": "\"whose\" sadece insanlar için değil, CANSIZ varlıklar için de kullanılabilir — burada \"ending\" romana [[dark]]AİTTİR[[/dark]], bu yüzden doğru cevap [[right]]\"whose\"[[/right]]tur; bazı öğrenciler \"whose\"un sadece kişilerle kullanılabileceğini zannederek bu tür sorularda yanlış şıkka yönelir."}, {"sentence": "The restaurant where we celebrated our anniversary last year has unfortunately closed down.", "answer_word": "where", "reasoning": "\"restaurant\" bir [[dark]]YER[[/dark]] ismi ve ardından öznesi tam olan bir cümle (\"we celebrated...\") geldiği için doğru cevap [[right]]\"where\"[[/right]]dir; [[wrong]]\"which/that\"[[/wrong]] kullanılsaydı cümlenin bir edatla (\"...AT last year\") tamamlanması gerekirdi."}]}$tagbd$::jsonb WHERE id = '31e0ff92-e2bb-492c-9a5c-f6db9135b75a';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "İlgi cümleciği ÖZNE konumundaysa (zamir+be atılabilir), fiilin AKTİF mi EDİLGEN mi olduğuna göre farklı bir kısaltma ortaya çıkar:", "items": [{"heading": "Kısaltma Türleri", "badge": "-ing / V3 / having+V3", "sub_rules": [{"condition": "Fiil [[amber]]AKTİF[[/amber]] ise zamir+be atılır, fiil [[b]]-ing[[/b]] (gerund/present participle) olur:", "from": "who is standing", "to": "standing"}, {"condition": "Fiil [[amber]]EDİLGEN[[/amber]] ise zamir+be atılır, geriye sadece [[b]]past participle (V3)[[/b]] kalır:", "from": "which was written", "to": "written"}, {"condition": "Ana eylemden [[amber]]ÖNCE[[/amber]] gerçekleşmiş bir eylemi vurgulamak için (perfect participle):", "from": "having + V3", "to": "having finished"}]}, {"heading": "-ing İle Başlayan Cümle Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Cümle [[b]]-ing[[/b]] ile başlıyorsa, bu kısmı zihninde parantez içine al ve cümlenin [[dark]]GERÇEK ANA FİİLİNİ[[/dark]] cümlenin geri kalanında ara — -ing yapısı ana fiil [[bad]]DEĞİLDİR[[/bad]]."}], "warning_text": "Bu ayrımı gözden kaçırmak YDS'de en sık yapılan hatalardan biridir."}, {"heading": "Kısaltılmış Cümlecik İçinde Ana Fiili Bulma", "badge": "Pratik", "body": [{"type": "text", "text": "\"The report (which was) submitted last week revealed major flaws.\" → \"The report submitted last week revealed major flaws.\""}, {"type": "example_check", "correct": "The report submitted last week revealed major flaws", "wrong_note": "\"submitted\" (V3, edilgen kısaltma) ana fiil değildir, cümlenin gerçek yüklemi \"revealed\"tır"}]}], "examples": [{"sentence": "The report submitted last week revealed major flaws.", "answer_word": "submitted", "reasoning": "Burada [[right]]\"submitted\"[[/right]] (V3, edilgen kısaltma: \"which was submitted\") ana fiil değildir, cümlenin gerçek yüklemi [[b]]\"revealed\"[[/b]]tır — bu ayrımı gözden kaçırmak YDS'de en sık yapılan hatalardan biridir."}, {"sentence": "The passengers waiting at the gate were informed about the delay.", "answer_word": "waiting", "reasoning": "Burada [[right]]\"waiting\"[[/right]] aktif bir eylemi (yolcuların kendi eylemi) anlattığı için -ing (present participle) kullanılır; cümlenin gerçek ana fiili [[b]]\"were informed\"[[/b]]dur, \"waiting\" sadece öznenin durumunu tanımlayan kısaltılmış bir cümleciktir."}, {"sentence": "Having finished all her assignments early, she decided to spend the rest of the evening reading a novel.", "answer_word": "Having finished", "reasoning": "Ana eylemden (karar verme) [[dark]]ÖNCE[[/dark]] tamamlanmış bir eylemi vurgulamak için \"having + V3\" (perfect participle) kullanılır → doğru cevap [[right]]\"Having finished\"[[/right]]dir."}, {"sentence": "The documents approved by the committee last week are now available for public review.", "answer_word": "approved", "reasoning": "Fiil [[dark]]EDİLGEN[[/dark]] olduğu için (\"which were approved\" ifadesinin kısaltılmış hali) geriye sadece past participle kalır → doğru cevap [[right]]\"approved\"[[/right]]tur (V3); [[wrong]]\"approving\"[[/wrong]] (aktif -ing) burada yanlıştır çünkü belgeler onaylamıyor, onaylanıyor."}]}$tagbd$::jsonb WHERE id = 'c7009f21-5574-444e-98dd-f1a114d2201d';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Emir/rica aktarımında doğru yapıyı seçmenin anahtarı, aktarılan fiilin hangi kalıbı aldığını bilmektir:", "items": [{"heading": "İki Temel Kalıp", "badge": "to mu, that mı?", "sub_rules": [{"condition": "[[amber]]tell, ask, order, advise, warn, urge, persuade, remind, invite, encourage, force[[/amber]] gibi emir/rica/tavsiye fiilleri:", "from": "KİŞİ", "to": "to + fiilin yalın hali"}, {"condition": "[[amber]]admit, argue, claim, deny, explain, insist, mention, point out, state, suggest[[/amber]] gibi fiiller kişi almaz:", "from": "(kişi yok)", "to": "that + özne + yüklem"}]}, {"heading": "Olumsuzlukta \"not\"un Yeri", "badge": "Kalıp Detayı", "body": [{"type": "text", "text": "Olumsuzlukta [[b]]\"not\"[[/b]] doğrudan [[q]]\"to\"[[/q]]'dan önce gelir."}, {"type": "example_check", "correct": "advised him not to skip breakfast", "wrong_note": "\"advised to not skip\" sırası yanlıştır"}]}, {"heading": "\"suggest\" / \"recommend\" Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[amber]]\"suggest\"[[/amber]] ve [[amber]]\"recommend\"[[/amber]] ASLA [[bad]]\"to + fiil\"[[/bad]] almaz; bunun yerine [[ok]]\"+ V-ing\"[[/ok]] ya da [[ok]]\"+ that + özne + should/yalın fiil\"[[/ok]] kullanılır."}], "warning_text": "\"suggested to go\" gibi bir yapı YDS'de klasik bir yanlış şık tuzağıdır."}, {"heading": "\"say\" ve \"tell\": Kişi Alır mı?", "badge": "Klasik Tuzak", "body": [{"type": "text", "text": "[[amber]]\"say\"[[/amber]] kişi almaz: [[bad]]\"said me\"[[/bad]] yanlış, [[ok]]\"said to me\"[[/ok]] doğrudur."}, {"type": "text", "text": "[[amber]]\"tell\"[[/amber]] ise kişiyi zorunlu kılar: [[bad]]\"told that...\"[[/bad]] yanlış, [[ok]]\"told me that...\"[[/ok]] doğrudur."}]}], "examples": [{"sentence": "He suggested leaving early.", "answer_word": "leaving early", "reasoning": "\"Why don't we leave early?\" şeklindeki öneri \"suggest\" ile aktarılırken [[right]]\"leaving early\"[[/right]] (+V-ing) ya da \"that we (should) leave early\" kullanılır; [[wrong]]\"suggested to leave early\"[[/wrong]] yapısı YDS'de klasik bir yanlış şık tuzağıdır çünkü \"suggest\" asla \"to + fiil\" almaz."}, {"sentence": "The mother told her son to finish his homework before dinner.", "answer_word": "to finish", "reasoning": "\"tell\" mutlaka bir KİŞİ alır ve \"kişi + [[right]]to finish[[/right]]\" kalıbını kullanır; [[wrong]]\"told to finish\"[[/wrong]] (kişisiz) ya da \"told that finish\" gibi bir yapı bu kalıba uymadığı için yanlıştır."}, {"sentence": "The doctor advised him not to skip breakfast every day.", "answer_word": "not to skip", "reasoning": "\"advise\" kalıbı \"kişi + to + fiil\" alır ve olumsuzlukta [[b]]\"not\"[[/b]] doğrudan \"to\"dan önce gelir → doğru cevap [[right]]\"not to skip\"[[/right]]; [[wrong]]\"advised to not skip\"[[/wrong]] bu kalıba uymadığı için yanlıştır."}, {"sentence": "He denied that he had taken the money.", "answer_word": "that he had taken the money", "reasoning": "\"deny\" kişi almaz ve \"[[right]]that he had taken the money[[/right]]\" kalıbını kullanır; [[wrong]]\"denied to take the money\"[[/wrong]] gibi bir yapı bu fiilin kalıbına uymadığı için YDS'de klasik bir tuzaktır."}]}$tagbd$::jsonb WHERE id = 'bed5059e-31fb-4397-863e-61db3cb37dc3';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Aktarılan cümlede zaman kaydırması (backshift) yapılıp yapılmayacağı, önce [[b]]reporting fiilin zamanına[[/b]] bakılarak belirlenir:", "items": [{"heading": "Zaman Kaydırma Tablosu (Fiil Zamanları)", "badge": "Backshift", "sub_rules": [{"condition": "Reporting fiil geçmişse [[amber]]present simple[[/amber]] →", "from": "present simple", "to": "past simple"}, {"condition": "Reporting fiil geçmişse [[amber]]present continuous[[/amber]] →", "from": "present continuous", "to": "past continuous"}, {"condition": "Reporting fiil geçmişse [[amber]]present perfect[[/amber]] →", "from": "present perfect", "to": "past perfect"}, {"condition": "Reporting fiil geçmişse [[amber]]simple past[[/amber]] →", "from": "simple past", "to": "past perfect"}]}, {"heading": "Zaman Kaydırma Tablosu (Modaller)", "badge": "Backshift", "sub_rules": [{"condition": "[[amber]]will[[/amber]] →", "from": "will", "to": "would"}, {"condition": "[[amber]]can[[/amber]] →", "from": "can", "to": "could"}, {"condition": "[[amber]]may[[/amber]] →", "from": "may", "to": "might"}, {"condition": "zorunluluk [[amber]]must[[/amber]] →", "from": "must", "to": "had to"}]}, {"heading": "Kaydırma Yapılmayan Durumlar", "badge": "İstisnalar", "body": [{"type": "text", "text": "Reporting fiil [[amber]]ŞİMDİKİ ZAMANDA[[/amber]] (says/tells) ise [[bad]]hiçbir kaydırma yapılmaz[[/bad]]."}, {"type": "text", "text": "[[b]]Değişmez gerçeklerde[[/b]] (\"The Earth revolves around the Sun\") kaydırma genelde [[amber]]opsiyoneldir[[/amber]]."}]}, {"heading": "Zaman/Yer İfadeleri ve Soru Aktarımı", "badge": "Ek Değişimler", "body": [{"type": "text", "text": "Zaman/yer ifadeleri de değişir: [[pair]]today->that day[[/pair]], [[pair]]tomorrow->the next day[[/pair]], [[pair]]yesterday->the day before[[/pair]], [[pair]]here->there[[/pair]], [[pair]]this->that[[/pair]]."}, {"type": "text", "text": "Yes/no soruları [[q]]if/whether[[/q]] ile bağlanır ve ÖZNE-YÜKLEM sırasına döner (soru sırası kaybolur): [[pair]]Do you like coffee?->He asked if I liked coffee.[[/pair]]"}, {"type": "text", "text": "Wh- sorularında soru kelimesi kalır ama [[b]]do/did[[/b]] yardımcı fiili kalkar: [[pair]]Where do you live?->He asked where I lived.[[/pair]]"}]}], "examples": [{"sentence": "She said that she would see me the next day.", "answer_word": "would see me the next day", "reasoning": "Hem [[q]]will->would[[/q]] hem [[q]]tomorrow->the next day[[/q]] değişimi birden uygulanır çünkü reporting fiil (said) geçmiş zamandadır → doğru cevap [[right]]\"would see me the next day\"[[/right]]dir."}, {"sentence": "She asked him if he had finished the report.", "answer_word": "if he had finished the report", "reasoning": "Hem soru sırası özne-yükleme döner (do/did yardımcı fiili düşer) hem de \"have finished\" (present perfect) bir basamak geriye kayarak \"had finished\" (past perfect) olur, çünkü reporting fiil (asked) geçmiş zamandadır → doğru cevap [[right]]\"if he had finished the report\"[[/right]]dir."}, {"sentence": "The artist said that she could finish the painting by the following week if I brought more canvas there.", "answer_word": "could finish the painting by the following week", "reasoning": "Hem [[q]]can->could[[/q]] hem [[q]]next week->the following week[[/q]] hem de [[q]]here->there[[/q]] değişimi birden uygulanır çünkü reporting fiil (said) geçmiş zamandadır; koşul cümlesindeki \"bring\" de \"brought\" olarak bir basamak geriye kayar → doğru cevap [[right]]\"could finish the painting by the following week\"[[/right]]dir."}, {"sentence": "The manager asked her why she had left the meeting early.", "answer_word": "why she had left the meeting early", "reasoning": "Soru kelimesi (\"why\") kalır ama \"did...leave\" yapısındaki \"did\" yardımcı fiili düşer ve \"left\" (past simple) bir basamak geriye kayarak \"had left\" (past perfect) olur, çünkü reporting fiil (asked) geçmiş zamandadır → doğru cevap [[right]]\"why she had left the meeting early\"[[/right]]dir."}]}$tagbd$::jsonb WHERE id = '2ecfae88-18b4-48b2-a71d-debf689ef2bf';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "İlgi zamiri (who/which/that) SADECE [[b]]iki şart birden[[/b]] sağlanınca atılabilir:", "items": [{"heading": "Atma Şartları", "badge": "İki Şart Birden", "sub_rules": [{"condition": "Şart 1 — cümlecik [[amber]]DEFINING[[/amber]] olmalı (virgül yok):", "from": "virgül yok", "to": "atılabilir"}, {"condition": "Şart 2 — zamir [[amber]]NESNE[[/amber]] konumunda olmalı (ardından başka bir özne+yüklem gelmeli):", "from": "nesne konumu", "to": "atılabilir"}]}, {"heading": "Zamirin ASLA Atılamadığı Durumlar", "badge": "İstisnalar", "body": [{"type": "text", "text": "Zamir [[amber]]ÖZNE[[/amber]] konumundaysa (ardından doğrudan yüklem geliyorsa) [[bad]]asla atılamaz[[/bad]]."}, {"type": "text", "text": "[[amber]]Non-defining[[/amber]] clause'da (virgüllü) da [[bad]]asla atılamaz[[/bad]]."}]}, {"heading": "Atma mı, Edilgen Kısaltma mı?", "badge": "Dikkat", "body": [{"type": "text", "text": "Bir şıkta zamir atılmış gibi görünüp cümlenin öznesi eksik kalmışsa, bu genelde [[dark]]edilgen kısaltma (reduced passive)[[/dark]]dir, zamirin basitçe atılması değildir."}, {"type": "example_check", "correct": "the book I bought yesterday was great", "wrong_note": "\"the book bought yesterday was great\" belirsizdir; bu edilgen kısaltmadır (\"the book which was bought\"), zamirin basitçe atılması değildir"}]}], "examples": [{"sentence": "The movie that we watched last night was boring.", "answer_word": "that", "reasoning": "[[right]]\"that\"[[/right]] nesne konumunda ve defining clause olduğu için atılabilir, her iki hâli de doğrudur. Ama \"The movie that was released last week is boring.\" cümlesinde \"that\" özne konumunda olduğu için atılamaz: [[wrong]]\"The movie was released last week is boring\"[[/wrong]] yanlıştır."}, {"sentence": "The restaurant, which my colleague recommended, turned out to be excellent.", "answer_word": "which", "reasoning": "Burada zamir nesne konumunda olsa da (recommended'ın nesnesi) cümlecik virgüllü yani [[dark]]NON-DEFINING[[/dark]] olduğu için [[right]]\"which\"[[/right]] atılamaz: [[wrong]]\"The restaurant, my colleague recommended, turned out...\"[[/wrong]] şeklinde zamiri çıkarmak yanlıştır — atma kuralı sadece defining clause'larda geçerlidir."}, {"sentence": "The laptop that I bought last month has already started malfunctioning.", "answer_word": "that", "reasoning": "[[right]]\"that\"[[/right]] burada \"bought\"ın nesnesi konumunda ve virgülsüz (defining) bir cümlecik olduğu için atılabilir, iki hâli de doğrudur: \"The laptop I bought last month...\" ya da \"The laptop that I bought last month...\" her ikisi de kabul edilir."}, {"sentence": "The scientist who discovered the vaccine was awarded a prestigious international prize.", "answer_word": "who", "reasoning": "Burada [[right]]\"who\"[[/right]] cümlenin öznesi konumundadır (ardından doğrudan \"discovered\" yüklemi gelir) → bu yüzden atılamaz: [[wrong]]\"The scientist discovered the vaccine was awarded...\"[[/wrong]] şeklinde zamiri çıkarmak cümleyi anlamsız ve gramer açısından hatalı hale getirir."}]}$tagbd$::jsonb WHERE id = '6b3ef7d7-206f-48b3-8886-4129990035b8';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]see / hear / watch / notice / feel[[/q]] gibi algı fiillerinden sonra nesne + fiil seçimi, eylemin TAMAMI mı yoksa bir ANI mı anlatıldığına göre değişir:", "items": [{"heading": "Tam Eylem mi, Yarım An mı?", "badge": "do / doing", "sub_rules": [{"condition": "Nesne + [[amber]]FİİL[[/amber]] (bare infinitive, to'suz) kullanılırsa eylemin [[dark]]BAŞINDAN SONUNA KADAR TAMAMI[[/dark]] gözlemlenmiştir:", "from": "I saw him cross the street", "to": "(tamamını gördüm)"}, {"condition": "Nesne + fiil[[amber]]-ING[[/amber]] kullanılırsa eylem [[dark]]SÜRERKEN, YARIM[[/dark]] bir anda yakalanmıştır:", "from": "I saw him crossing the street", "to": "(ortasında bir anda gördüm)"}]}, {"heading": "Cümledeki İpuçlarını Tanı", "badge": "Pratik", "body": [{"type": "text", "text": "[[amber]]\"for a while\", \"as I passed by\", \"when I looked out\"[[/amber]] gibi KISA BİR ANA veya SÜRÜP GİTMEYE işaret eden ifadeler varsa [[q]]-ing[[/q]] formu tercih edilir."}, {"type": "text", "text": "Eylemin [[dark]]SONUCU/TAMAMLANMASI[[/dark]] net bir şekilde vurgulanıyorsa (sonrasında ne olduğu anlatılıyorsa) [[q]]bare infinitive[[/q]] doğrudur."}]}], "examples": [{"sentence": "I saw the thief steal the wallet and then run away.", "answer_word": "steal", "reasoning": "Cümlenin devamında \"run away\" (kaçtı) ile hırsızlığın [[dark]]TAMAMLANDIĞI[[/dark]] ve sonucunun anlatıldığı belli oluyor → doğru cevap bare infinitive [[right]]\"steal\"[[/right]]dir, eylemin başından sonuna kadarı gözlemlenmiştir."}, {"sentence": "As I walked past the classroom, I heard the students singing a song.", "answer_word": "singing", "reasoning": "Burada sadece yoldan geçerken, şarkının [[dark]]SÜRERKEN[[/dark]] bir anına kulak misafiri olunmuş, başlangıcı veya bitişi bilinmiyor → doğru cevap -ing formu [[right]]\"singing\"[[/right]]dir."}, {"sentence": "From my window, I watched the workers build the entire fence over the course of the afternoon.", "answer_word": "build", "reasoning": "Cümlede \"over the course of the afternoon\" ifadesi eylemin [[dark]]BAŞINDAN SONUNA KADAR[[/dark]] tamamının izlendiğini gösteriyor → doğru cevap bare infinitive [[right]]\"build\"[[/right]]dir."}, {"sentence": "I noticed smoke coming from the kitchen window as I walked past the building.", "answer_word": "coming", "reasoning": "Burada sadece yoldan geçerken kısa bir an için fark edilen, [[dark]]SÜREN[[/dark]] bir eylem anlatılıyor, başlangıcı veya sonu bilinmiyor → doğru cevap -ing formu [[right]]\"coming\"[[/right]]dir."}]}$tagbd$::jsonb WHERE id = 'f0c19f77-f6dc-4f7f-8e5d-3afd95015fa5';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir phrasal verb'ün [[q]]ayrılabilir[[/q]] mi [[q]]ayrılamaz[[/q]] mı olduğunu anlamanın en kesin yolu, nesnenin [[b]]ZAMİR[[/b]] olduğu bir cümle kurmaktır:", "items": [{"heading": "Ayrılabilir Phrasal Verb'ler", "badge": "turn off, give up, pick up, work out, call off", "body": [{"type": "text", "text": "Nesne İSİM ise fiil+parçacığın öncesine veya arasına girebilir: [[pair]]turn off the light->turn the light off[[/pair]]."}, {"type": "text", "text": "Nesne [[amber]]ZAMİR[[/amber]] (it, him, her, them) ise [[dark]]MUTLAKA[[/dark]] araya girmek zorundadır."}, {"type": "example_check", "correct": "turn it off", "wrong_note": "\"turn off it\" kesinlikle yanlıştır"}]}, {"heading": "Ayrılamaz Phrasal Verb'ler", "badge": "look after, come across, run into, deal with, get over", "body": [{"type": "text", "text": "Nesne ne isim ne de zamir olsun, [[dark]]HER ZAMAN[[/dark]] fiil+parçacık grubunun sonrasına gelir ve [[bad]]asla araya giremez[[/bad]]."}, {"type": "example_check", "correct": "look after them", "wrong_note": "\"look them after\" yanlıştır"}]}], "examples": [{"sentence": "She had to cancel the meeting, so she decided to call it off.", "answer_word": "it off", "reasoning": "Boşluktaki nesne \"the meeting\"in yerini tutan bir zamirdir (it) ve \"call off\" ayrılabilir bir phrasal verb olduğu için zamir kullanıldığında araya girmesi [[dark]]ZORUNLUDUR[[/dark]] → doğru kuruluş [[right]]\"call it off\"[[/right]]tur, [[wrong]]\"call off it\"[[/wrong]] yanlıştır."}, {"sentence": "I unexpectedly ran into an old friend of mine while shopping downtown.", "answer_word": "ran into", "reasoning": "[[right]]\"run into\"[[/right]] (rastlamak) ayrılamaz bir phrasal verb'dür, nesne ister isim ister zamir olsun her zaman grubun sonrasına gelir; burada ayırma denemek ([[wrong]]\"run an old friend into\"[[/wrong]]) anlamsız ve yanlış olurdu."}, {"sentence": "He realized he'd forgotten his umbrella at the office, so he had to go back and pick it up before the rain started.", "answer_word": "pick it up", "reasoning": "Boşluktaki nesne daha önce geçen \"his umbrella\"nın yerini tutan bir zamirdir (it) ve \"pick up\" ayrılabilir bir phrasal verb olduğu için zamir mutlaka araya girmelidir → doğru kuruluş [[right]]\"pick it up\"[[/right]]tur."}, {"sentence": "While her sister was away on business, she kindly offered to look after them during the entire trip.", "answer_word": "look after them", "reasoning": "[[right]]\"look after\"[[/right]] (bakmak, ilgilenmek) ayrılamaz bir phrasal verb'dür, bu yüzden nesne zamir bile olsa grubun sonrasına gelir → doğru kuruluş \"look after them\"dir; [[wrong]]\"look them after\"[[/wrong]] şeklinde araya sokmak kesinlikle yanlıştır."}]}$tagbd$::jsonb WHERE id = 'a076c136-0045-4a67-989d-a162100d3b13';
